import { Path, PathEffect, hex } from "retiam";

const subtleLine = new Path("M -20 0 C -10 12, 10 -12, 20 0", {
    strokeShader: PathEffect.DynamicStroke({
        randomness: 0.25,   // low randomness -> gentle, subtle breathing
        asymmetry: 0.20,    // mild lateral inequality
        spontaneity: 0.30
    })
});
subtleLine.paint.setStroke(1.2, hex("#38bdf8"));

const dramaticFlourish = new Path("M -30 0 C -15 25, 15 -25, 30 0", {
    strokeShader: PathEffect.Calligraphic({
        variation: 1.5,     // boosted variation -> wild expressive swells
        asymmetry: 0.70,    // strong belly-vs-spine lateral tilt
        taper: [0.15, 0.22] // graceful touchdown and tail tapers
    })
});
dramaticFlourish.paint.setStroke(1.8, hex("#f472b6"));

const uniformLine = new Path("M -20 0 L 20 0", {
    strokeShader: PathEffect.DynamicStroke({
        variation: 0.0,     // completely turns off width variation
        asymmetry: 0.0      // symmetric edges
    })
});
uniformLine.paint.setStroke(1.0, hex("#ffffff"));

import { Circle, PathEffect, hex, Color } from "retiam";

const breathingCircle = new Circle(5.0, {
    strokeShader: PathEffect.Brush({
        frequency: 2.0,
        asymmetry: 0.35,
        inkDensity: 0.55,
        isClosed: true      // wraps periodic 2D noise around 360° with zero seam
    })
});
breathingCircle.paint.setStroke(1.4, hex("#34d399"));
breathingCircle.paint.fill = new Color(0.02, 0.12, 0.08, 0.3);

const chainedShader = PathEffect.Gradient([hex("#38bdf8"), hex("#ec4899"), hex("#fbbf24")])
    .DynamicStroke({
        variation: 1.2,
        asymmetry: 0.50,
        inkDensity: 0.45
    })
    .Glow(0.25);

const glowingRibbon = new Path("M -25 -5 C -10 15, 10 -15, 25 5", {
    strokeShader: chainedShader
});
glowingRibbon.paint.setStroke(1.6, hex("#ffffff"));

import { Scene, Path, PathEffect, Create, Rate, hex } from "retiam";

export class DynamicDrawingScene extends Scene {
    public async run() {
        const signature = new Path("M -25 0 C -15 20, 0 -20, 15 15 S 30 -10, 35 0", {
            strokeShader: PathEffect.Brush({
                frequency: 1.5,
                spontaneity: 0.40,
                inkDensity: 0.50
            })
        });
        signature.paint.setStroke(1.5, hex("#2dd4bf"));
        this.add(signature);

        await this.play(new Create(signature, {
            duration: 2500,
            rate_func: Rate.easeInOutCubic()
        }));
    }
}

import { Path, PathEffect, WobbleModifier, hex } from "retiam";

const sketchLine = new Path("M -30 0 C -15 10, 15 -10, 30 0", {
    strokeShader: PathEffect.Sketch({
        minWidth: 0.5,      // lightest the pen gets (default 0.5)
        maxWidth: 1.0,      // heaviest the pen gets (default 1.0, never above the stroke width)
        variation: 1.0,     // how strongly the width swells and thins
        bias: 0.0,          // > 0 stays heavy, < 0 stays light
        wavelength: 1.5,    // world units per swell
        pressure: 0.6,      // lighter where the pen lands and lifts
        grain: 0.0          // optional paper-tooth edge grain
    })
});
sketchLine.paint.setStroke(1.7, hex("#38bdf8"));
sketchLine.setModifier(new WobbleModifier({ roughness: 0.3 }));
